"""Build the compact, self-contained comparison visual from audited results."""
from pathlib import Path
import argparse,json,html

def render(root):
 data=json.loads((root/'transfer-analysis.json').read_text());cost=json.loads((root/'cost-analysis.json').read_text())['costs'];rows=[]
 labels=['480 updates · DEV12','960 updates · DEV12','1,920 updates · DEV12','1,920 updates · natural24']
 for label,v in zip(labels,data['comparisons']):
  lo,hi=v['bootstrap95_percent'];mean=v['broader_percent'];left=(lo+6)*10;right=(hi+6)*10;point=(mean+6)*10
  rows.append(f'<div class="row"><span>{label}</span><div class="plot"><i class="zero"></i><i class="interval" style="left:{left:.3f}%;width:{right-left:.3f}%"></i><i class="dot" style="left:{point:.3f}%"></i></div><b>{mean:+.2f}%</b></div>')
 bars=[]
 for arm,label in [('dflash_Q4KM','DFlash'),('paid5760','Current W1A8')]:
  v=cost[arm];g=v['root_ms_per_round']['draft_generate'];c=v['root_ms_per_round']['draft_catchup'];total=v['full_draft_ms_per_round']
  bars.append(f'<div class="barrow"><span>{label}</span><div class="bartrack"><div class="generation" style="width:{g/2.6*100:.3f}%">{g:.2f}</div><div class="catchup" style="width:{c/2.6*100:.3f}%">{c:.2f}</div></div><b>{total:.2f} ms</b></div>')
 return '''<!doctype html><html><head><meta charset="utf-8"><style>
body{margin:0;font-family:var(--font-sans);color:var(--foreground)}h3{font-size:16px;margin:0 0 10px}p{font-size:12px;line-height:1.5;color:var(--muted-foreground);margin:8px 0 20px}.row{display:grid;grid-template-columns:155px minmax(120px,1fr) 62px;gap:12px;align-items:center;height:38px;font-size:12px}.plot{position:relative;height:30px}.zero{position:absolute;left:60%;top:0;height:30px;border-left:1px dashed var(--border)}.interval{position:absolute;top:14px;height:3px;background:var(--chart-1)}.interval:before,.interval:after{content:"";position:absolute;top:-4px;width:2px;height:11px;background:var(--chart-1)}.interval:after{right:0}.dot{position:absolute;top:10px;width:10px;height:10px;transform:translateX(-50%);background:var(--chart-1);border-radius:50%}.axis{display:grid;grid-template-columns:155px minmax(120px,1fr) 62px;gap:12px;font-size:11px;color:var(--muted-foreground)}.axis div{position:relative;height:14px}.axis div span:nth-child(2){position:absolute;left:60%;transform:translateX(-50%)}.axis div span:last-child{float:right}.barrow{display:grid;grid-template-columns:110px minmax(120px,1fr) 66px;gap:12px;align-items:center;height:46px;font-size:12px}.bartrack{display:flex;height:30px}.bartrack div{display:flex;align-items:center;justify-content:center;color:var(--foreground);font-size:12px}.generation{background:var(--chart-1)}.catchup{background:var(--chart-2)}.legend{display:flex;gap:18px;font-size:12px;margin:8px 0}.swatch{display:inline-block;width:10px;height:10px;margin-right:5px}b{font-weight:600;font-variant-numeric:tabular-nums}section+section{margin-top:24px}@media(max-width:480px){.row,.axis{grid-template-columns:113px minmax(100px,1fr) 48px;gap:6px;font-size:10px}.barrow{grid-template-columns:86px minmax(100px,1fr) 53px;gap:6px;font-size:11px}.bartrack div{font-size:10px}}
</style></head><body><section><h3>Broader data: no established speed gain</h3>'''+''.join(rows)+'''<div class="axis"><span></span><div><span>−6%</span><span>0</span><span>+4%</span></div><span></span></div><p>Change versus the same-update control; lines show 95% intervals. Five repetitions on previously consumed prompts. Every interval crosses zero.</p></section><section><h3>Catch-up reverses the narrow draft-time advantage</h3><div class="legend"><span><i class="swatch generation"></i>Draft generation</span><span><i class="swatch catchup"></i>Catch-up</span></div>'''+''.join(bars)+'''<p>Host milliseconds per verification round; lower is better. Totals include negligible acceptance bookkeeping. Current complete draft work is 10.4% more costly (95% interval 7.9–12.6%). These are serving costs, not isolated GPU kernel times.</p></section></body></html>'''
if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('--campaign',type=Path,required=True);p.add_argument('--out',type=Path,required=True);a=p.parse_args();a.out.write_text(render(a.campaign))
